def drive(me, enemy, arena):
    dx = enemy.x - me.x
    dy = enemy.y - me.y
    dist = hypot(dx, dy)
    if dist < 0.001:
        return (0, 0)
    r = hypot(me.x, me.y)
    if r > 5.0:
        k = (r - 5.0) / 1.5
        if k > 2.0:
            k = 2.0
        dx += (-me.x / r) * k * dist
        dy += (-me.y / r) * k * dist
    targetx = me.x + dx
    targety = me.y + dy
    b = bearing_to(targetx, targety)
    rpm = 0.0
    try:
        rpm = me.weapons["front"]["rpm"]
    except Exception:
        rpm = 0.0
    throttle = 1.0
    if rpm < 1200 and dist > 2.0:
        throttle = 0.55
    if abs(b) > 90:
        if b > 0:
            return (-throttle, throttle)
        else:
            return (throttle, -throttle)
    turn = b / 45.0
    if turn > 1.0:
        turn = 1.0
    if turn < -1.0:
        turn = -1.0
    left = throttle * (1.0 - turn)
    right = throttle * (1.0 + turn)
    if left > 1.0:
        left = 1.0
    if left < -1.0:
        left = -1.0
    if right > 1.0:
        right = 1.0
    if right < -1.0:
        right = -1.0
    return (left, right)

